// Create a particle system for trails
const trailParticles = [];
const trailCount = 100;
const trailGeometry = new THREE.BufferGeometry();
const trailMaterial = new THREE.PointsMaterial({
color: 0xffffff,
size: 0.1,
transparent: true,
opacity: 0.7,
});
for (let i = 0; i < trailCount; i++) {
const particle = new THREE.Vector3(
Math.random() * gridSize - gridSize / 2,
Math.random() * gridSize - gridSize / 2,
Math.random() * gridSize - gridSize / 2
);
trailParticles.push(particle);
}
trailGeometry.setAttribute('position', new THREE.Float32BufferAttribute(trailParticles.flat(), 3));
const trailMesh = new THREE.Points(trailGeometry, trailMaterial);
scene.add(trailMesh);
// Update particles over time
function updateParticles() {
for (let i = 0; i < trailParticles.length; i++) {
const particle = trailParticles[i];
// Move particles toward a random sphere
const targetSphere = spheres[Math.floor(Math.random() * spheres.length)];
particle.lerp(targetSphere.position, 0.05);
}
trailGeometry.attributes.position.needsUpdate = true;
}
