// Generate noise for positions/colors
const noise = new Noise();
const gridSize = 10;
const sphereRadius = 0.5;
// Create a grid of spheres with noise-based positions
const spheres = [];
for (let x = 0; x < gridSize; x++) {
for (let y = 0; y < gridSize; y++) {
for (let z = 0; z < gridSize; z++) {
// Apply Perlin noise to position (scaled to [-1, 1])
const nx = noise.simplex2(x  0.1, y  0.1) * 2 - 1;
const ny = noise.simplex2(y  0.1, z  0.1) * 2 - 1;
const nz = noise.simplex2(z  0.1, x  0.1) * 2 - 1;
const position = new THREE.Vector3(
x - gridSize / 2 + nx,
y - gridSize / 2 + ny,
z - gridSize / 2 + nz
);
// Color based on noise
const color = new THREE.Color();
color.setHSL(
(noise.simplex2(x  0.2, y  0.2) + 1) / 2, // Hue (0-1)
0.7 + noise.simplex2(x  0.3, z  0.3) * 0.3, // Saturation
0.5 + noise.simplex2(y  0.4, z  0.4) * 0.5 // Lightness
);
const sphere = new THREE.Mesh(
new THREE.SphereGeometry(sphereRadius, 32, 32),
new THREE.MeshStandardMaterial({ color })
);
sphere.position.copy(position);
spheres.push(sphere);
scene.add(sphere);
}
}
}
