# **Roasted Bean Particles: A Total Grind**
*A chaotic, interactive particle system where you grind, roast, and manipulate coffee beans in a 3D space—with physics, visual feedback, and emergent behavior!*

---

## **Concept Overview**
**Roasted Bean Particles: A Total Grind** is a **3D interactive particle system** where users manipulate coffee beans (as spheres) in a virtual grinder/roaster. The goal is to **control the grinding, roasting, and dispersion** of beans to achieve the perfect brew—while dealing with physics, heat, and emergent chaos.

### **Core Mechanics:**
1. **Grinding Phase** – Crush beans into smaller particles (spheres) with varying sizes and colors.
2. **Roasting Phase** – Apply heat (via drag, color shifts, and particle interactions) to develop flavor.
3. **Dispersion Phase** – Scatter the roasted particles into a brewing vessel (or let them escape in a chaotic explosion).
4. **Physics & Emergent Behavior** – Beans react to gravity, collisions, and user input in unpredictable ways.
5. **UI Controls** – Adjust grind fineness, roast intensity, and dispersion force.

---

## **Technical Implementation (Three.js + Custom Physics)**
Here’s a modified version of your sphere system, now with **coffee-themed physics, roasting effects, and grinding mechanics**:

### **HTML/CSS Setup**
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Roasted Bean Particles: A Total Grind</title>
  <style>
    body { margin: 0; overflow: hidden; background: #1a1a1a; }
    #ui { position: absolute; top: 20px; left: 20px; color: white; }
    button, input { padding: 8px; margin: 5px; }
    .slider { width: 200px; }
  </style>
</head>
<body>
  <div id="ui">
    <h1>Roasted Bean Particles</h1>
    <div>
      <label>Grind Fineness: <span id="grindDisplay">Medium</span></label>
      <input type="range" id="grindFineness" min="0.1" max="2.0" step="0.1" value="1.0" class="slider">
    </div>
    <div>
      <label>Roast Intensity: <span id="roastDisplay">Low</span></label>
      <input type="range" id="roastIntensity" min="0" max="100" value="30" class="slider">
    </div>
    <div>
      <label>Dispersion Force: <span id="dispersionDisplay">Normal</span></label>
      <input type="range" id="dispersionForce" min="0" max="10" step="0.5" value="3" class="slider">
    </div>
    <button id="startGrinding">Start Grinding</button>
    <button id="startRoasting">Start Roasting</button>
    <button id="dispenseBeans">Dispense!</button>
    <button id="reset">Reset</button>
  </div>
  <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new THREE.OrbitControls(camera, renderer.domElement);
    camera.position.set(0, 10, 20);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x404040);
    scene.add(ambientLight);
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(1, 1, 1);
    scene.add(directionalLight);

    // Particle system
    const beans = [];
    let isGrinding = false;
    let isRoasting = false;
    let dispersionForce = 3;
    let grindFineness = 1.0;
    let roastIntensity = 30;

    // UI references
    const ui = {
      grindFineness: document.getElementById('grindFineness'),
      roastIntensity: document.getElementById('roastIntensity'),
      dispersionForce: document.getElementById('dispersionForce'),
      grindDisplay: document.getElementById('grindDisplay'),
      roastDisplay: document.getElementById('roastDisplay'),
      dispersionDisplay: document.getElementById('dispersionDisplay'),
      startGrinding: document.getElementById('startGrinding'),
      startRoasting: document.getElementById('startRoasting'),
      dispenseBeans: document.getElementById('dispenseBeans'),
      reset: document.getElementById('reset')
    };

    // Initialize beans (as spheres)
    function initBeans(count = 50) {
      beans.forEach(bean => scene.remove(bean));
      beans.length = 0;

      for (let i = 0; i < count; i++) {
        const size = Math.random() * 0.5 + 0.2; // Random size
        const geometry = new THREE.SphereGeometry(size, 16, 16);
        const color = new THREE.Color(
          Math.random() * 0.3 + 0.2, // Brownish
          Math.random() * 0.2 + 0.1,
          Math.random() * 0.1 + 0.05
        );
        const material = new THREE.MeshStandardMaterial({
          color: color,
          roughness: 0.4,
          metalness: 0.1,
          transparent: true,
          opacity: 0.8
        });
        const bean = new THREE.Mesh(geometry, material);
        bean.position.set(
          (Math.random() - 0.5) * 10,
          Math.random() * 5 + 5,
          (Math.random() - 0.5) * 10
        );
        bean.userData = {
          originalSize: size,
          originalColor: color.clone(),
          velocity: new THREE.Vector3(
            (Math.random() - 0.5) * 0.5,
            Math.random() * 0.5,
            (Math.random() - 0.5) * 0.5
          ),
          roastProgress: 0,
          isGround: false
        };
        scene.add(bean);
        beans.push(bean);
      }
    }

    // Grinding effect (splitting beans into smaller particles)
    function grindBeans() {
      if (isGrinding) return;
      isGrinding = true;
      beans.forEach(bean => {
        const originalSize = bean.userData.originalSize;
        const newSize = originalSize / grindFineness;
        const count = Math.floor(originalSize / newSize) + 1;

        // Split into smaller beans
        for (let i = 0; i < count; i++) {
          const newBean = bean.clone();
          newBean.scale.set(newSize, newSize, newSize);
          newBean.position.add(
            (Math.random() - 0.5) * originalSize * 0.5,
            (Math.random() - 0.5) * originalSize * 0.3,
            (Math.random() - 0.5) * originalSize * 0.5
          );
          newBean.userData.velocity.multiplyScalar(1.5);
          scene.add(newBean);
          beans.push(newBean);
        }
        scene.remove(bean);
      });
      isGrinding = false;
    }

    // Roasting effect (color shift, heat glow)
    function roastBeans() {
      if (isRoasting) return;
      isRoasting = true;
      beans.forEach(bean => {
        const progress = Math.min(bean.userData.roastProgress + 0.05, 1);
        bean.userData.roastProgress = progress;

        // Color shift (from brown to dark brown/black)
        const r = Math.max(0.2, 0.2 + progress * 0.3);
        const g = Math.max(0.1, 0.1 + progress * 0.1);
        const b = Math.max(0.05, 0.05 + progress * 0.05);
        bean.material.color.setRGB(r, g, b);

        // Add glow effect
        if (progress > 0.7) {
          const glow = new THREE.PointLight(0xffcc00, 0.5, 1);
          glow.position.copy(bean.position);
          scene.add(glow

