```javascript
// Add fluid properties to spheres
function createFluidSphere(x, y, z, properties) {
  const geometry = new THREE.SphereGeometry(currentSphereSize, 32, 32);
  const material = new THREE.MeshStandardMaterial({
    color: properties.color || getRandomColor(),
    roughness: properties.viscosity || 0.3,
    metalness: 0.1,
    transparent: true,
    opacity: properties.opacity || 0.8,
  });
  const sphere = new THREE.Mesh(geometry, material);
  sphere.position.set(x, y, z);
  sphere.userData = {
    originalPosition: sphere.position.clone(),
    originalSize: currentSphereSize,
    id: spheres.length,
    layout: currentGridLayout,
    properties: properties, // { viscosity, temperature, acidity, etc. }
    isFluid: true,
  };
  scene.add(sphere);
  spheres.push(sphere);
  return sphere;
}

// Update physics for fluid spheres
function updateFluidPhysics() {
  spheres.forEach(sphere => {
    if (!sphere.userData.isFluid) return;

    // Buoyancy (temperature-based)
    const temp = sphere.userData.properties.temperature || 0;
    const gravityEffect = temp > 0 ? 0.01 : -0.01; // Hot rises, cold sinks
    sphere.position.y += gravityEffect;

    // Surface tension (merge nearby spheres)
    const nearbySpheres = spheres.filter(s =>
      s !== sphere &&
      s.userData.isFluid &&
      s.position.distanceTo(sphere.position) < currentSphereSize * 2
    );

    if (nearbySpheres.length > 0) {
      // Merge with closest sphere (simplified)
      const closest = nearbySpheres.reduce((a, b) =>
        a.position.distanceTo(sphere.position) < b.position.distanceTo(sphere.position) ? a : b
      );
      mergeSpheres(sphere, closest);
    }
  });
}

// Merge two spheres into one
function mergeSpheres(sphere1, sphere2) {
  const mergedProps = {
    color: new THREE.Color().lerpColors(sphere1.material.color, sphere2.material.color, 0.5),
    viscosity: (sphere1.userData.properties.viscosity + sphere2.userData.properties.viscosity) / 2,
    temperature: (sphere1.userData.properties.temperature + sphere2.userData.properties.temperature) / 2,
  };
  const mergedSphere = createFluidSphere(
    (sphere1.position.x + sphere2.position.x) / 2,
    (sphere1.position.y + sphere2.position.y) / 2,
    (sphere1.position.z + sphere2.position.z) / 2,
    mergedProps
  );
  mergedSphere.scale.set(
    sphere1.scale.x + sphere2.scale.x,
    sphere1.scale.y + sphere2.scale.y,
    sphere1.scale.z + sphere2.scale.z
  );
  scene.remove(sphere1);
  scene.remove(sphere2);
  spheres = spheres.filter(s => s !== sphere1 && s !== sphere2);
  spheres.push(mergedSphere);
}

// Update grid with fluid properties
function updateGrid() {
  spheres.forEach(sphere => scene.remove(sphere));
  spheres = [];

  const count = Math.min(currentSphereCount, 256);
  for (let i = 0; i < count; i++) {
    let row = Math.floor(i / cols);
    let col = i % cols;
    let x = (col - cols/2) * currentSpacing;
    let y = (row - rows/2) * currentSpacing;
    let z = 0;

    // Assign random fluid properties
    const properties = {
      color: getRandomColor(),
      viscosity: Math.random() * 0.5 + 0.3, // 0.3-0.8
      temperature: Math.random() > 0.5 ? 1 : -1, // Hot or cold
      acidity: Math.random() > 0.5 ? "sweet" : "sour", // Placeholder
    };

    createFluidSphere(x, y, z, properties);
  }
}
